INSERT INTO contact_mls_groups(cid_number,group_id,creator_device_id,group_revision,member_device_ids) SELECT '', 'assertion', '', NULL, '[]' WHERE NOT EXISTS(SELECT 1 FROM contact_mls_operations o WHERE o.cid_number=json_extract(?1,'$.auth.cid_number') AND o.operation_id=json_extract(?1,'$.operation.operation_id') AND o.device_id=json_extract(?1,'$.auth.device_id') AND o.group_revision=json_extract(?1,'$.operation.group_revision') AND o.operation_kind=json_extract(?1,'$.operation.operation_kind') AND o.target_device_ids=json_extract(?1,'$.operation.target_device_ids') AND o.result_json=json_extract(?1,'$.result_json') AND o.committed_at IS NOT NULL) AND NOT EXISTS(SELECT 1 FROM contact_mls_operations o WHERE o.cid_number=json_extract(?1,'$.auth.cid_number') AND o.operation_id=json_extract(?1,'$.operation.operation_id') AND o.device_id=json_extract(?1,'$.auth.device_id') AND o.group_revision=json_extract(?1,'$.operation.group_revision') AND o.operation_kind=json_extract(?1,'$.operation.operation_kind') AND o.target_device_ids=json_extract(?1,'$.operation.target_device_ids') AND o.committed_at IS NULL AND EXISTS(SELECT 1 FROM contact_mls_groups g WHERE g.cid_number=json_extract(?1,'$.auth.cid_number') AND g.group_id=json_extract(?1,'$.group.group_id') AND g.group_revision=json_extract(?1,'$.group.group_revision') AND g.member_device_ids=json_extract(?1,'$.group.member_device_ids') AND g.pending_operation_id=o.operation_id));
